int main(){try{auto resource=std::make_unique<Resource>();auto storage=std::make_unique<std::aligned_storage_t<sizeof(T),alignof(T)>>();std::vector<unsigned char>snapshot(sizeof(T));uint64_t graphs=0,phases=0,rejects=0,guards=0,reads=0,writes=0,nestedGraphs=0,nativeVoiceJobs=0,nativeAutomaticJobs=0;uint32_t components=0;Resolver resolver;
 const auto run=[&](Config c){seed(*resource,c);auto&r=*resource;T::Input in{c.event,c.pressed};tracking=true;auto*s=new(storage.get())T(T::Kind(c.kind),in);tracking=false;uint64_t count=0;unsigned hooks=0,voiceJobs=0,automaticJobs=0;bool voiceEntry=false,automaticEntry=false;while(!s->complete()){
 if(c.sceneNested)if(const auto*ui=s->ui()){
  bool atVoice=false;if(const auto*v=ui->task<ks::StateVoiceRefreshService>())if(const auto*t=v->task<ks::VoiceRefreshTask>())atVoice=t->stage()==ks::VoiceRefreshTask::Stage::ZeroIndex;if(atVoice&&!voiceEntry)++voiceJobs;voiceEntry=atVoice;
  bool atAutomatic=false;if(const auto*f=ui->coordinator())if(f->kind()==ks::StateFieldService::Kind::AutomaticEdit)if(const auto*w=f->task<ks::StateEditWorkflowTask>())atAutomatic=w->stage()==ks::StateEditWorkflowTask::Stage::ReadAutomaticIndex;if(atAutomatic&&!automaticEntry)++automaticJobs;automaticEntry=atAutomatic;
  if(!hooks)if(const auto*refresh=ui->refresh())if(const auto*bank=refresh->task<ks::StateBankNavigationTask>())if(bank->stage()==ks::StateBankNavigationTask::Stage::ReadRefreshLatch){r.byte(0x1679e,8);r.byte(0x1679d,64);r.byte(0x16793,28);r.byte(0x16792,1);r.byte(0x1679f,0);r.byte(0x16790,0);r.byte(0x167a0,0);hooks=1;}
 }
 const auto cost=s->nextClocks(r.previous);check(cost,"Missing pure edit action phase");r.phase(cost);const auto component=s->component();const auto mask=s->components();const auto critical=s->critical();const auto before=s->summary().presentation;const auto prev=r.previous;std::memcpy(snapshot.data(),s,sizeof(T));tracking=true;const auto rejected=s->advanceBefore(cost-1,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,prev);tracking=false;check(!rejected&&!r.size&&!std::memcmp(snapshot.data(),s,sizeof(T))&&component==s->component()&&mask==s->components()&&critical==s->critical()&&before==s->summary().presentation&&cost==s->nextClocks(prev),"Insufficient edit action budget changed state/resources");++rejects;tracking=true;const auto used=s->advanceBefore(cost,[&](uint32_t a,unsigned dt){++reads;return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){++writes;r.write(a,v,dt);},resolver,prev);tracking=false;check(used==cost,"Pure edit action phase cost");if(s->effect().write)r.previous=-1;if(++count>=1000000){std::cerr<<"stall kind="<<c.kind<<" seed="<<c.seed<<" component="<<unsigned(s->component())<<" action="<<unsigned(s->actionTask().stage())<<"\n";if(s->ui())std::cerr<<"ui component="<<unsigned(s->ui()->component())<<" depth="<<s->ui()->depth()<<"\n";throw std::logic_error("Pure edit action graph stalled");}++phases;}
 const auto&out=s->summary();if(c.kind==4)check(r.m[0x167fb]==0&&out.clearDigits,"ClearDigits independent oracle");if(c.kind==5)check(!r.m[0x16784]&&!r.m[0x16792],"ClearEdit independent oracle");if(c.kind==0&&c.pressed&&!c.page&&!c.sceneNested)check(r.m[0x16784]==uint8_t(c.edit^1)&&!r.m[0x16792]&&!r.m[0x167fb]&&out.ui,"ToggleEdit independent oracle");if(c.kind==1&&uint8_t(c.event>>8)&&!c.page&&!c.sceneNested){const auto expected=uint8_t(c.event)==c.screen?uint8_t(c.edit^1):uint8_t(1);check(r.m[0x16784]==expected&&!r.m[0x16792]&&!r.m[0x167fb]&&out.ui,"SelectEdit independent oracle");}if((c.kind==2||c.kind==3)&&c.pressed)check(out.apply&&s->apply()->complete()&&out.reference==c.source+(c.kind==2?215u:213u),"Complete Apply/reference oracle");if(c.sceneNested){check(out.ui&&out.clearDigits&&out.editAfter==(c.kind==0?uint8_t(c.edit^1):uint8_t(c.event)==c.screen?uint8_t(c.edit^1):uint8_t(1)),"Recursive caller edit result");check(hooks==1&&voiceJobs>=1&&automaticJobs>=2,"Recursive UI/Automatic/Scene/Voice branch was not observed");++nestedGraphs;nativeVoiceJobs+=voiceJobs;nativeAutomaticJobs+=automaticJobs;}components|=s->components();tracking=true;s->~T();tracking=false;++graphs;
 };
 for(unsigned kind=0;kind<7;++kind)for(unsigned n=0;n<32;++n){Config c;c.kind=kind;c.seed=n;c.page=n&8?1:0;c.edit=uint8_t(n&3);c.screen=uint8_t(n&1?11:10);c.hardware=uint8_t(n&16?0:1);if(!c.hardware&&kind==0)c.screen=9;c.event=uint16_t(((n&4?0:1)<<8)|11);c.pressed=!(n&4);if(n&2){c.source=0x80030001;c.live=0x42034001;}run(c);}
 for(unsigned kind:{2u,3u})for(unsigned value=0;value<256;++value){Config c;c.kind=kind;c.seed=value;c.event=0x0105;c.source=0x30000;run(c);}
 for(unsigned kind:{0u,1u})for(unsigned edit:{0u,1u,127u,128u,255u})for(unsigned event:{0u,1u,127u,128u,255u}){Config c;c.kind=kind;c.edit=uint8_t(edit);c.event=uint16_t((event<<8)|11);c.hardware=0;run(c);}
 for(unsigned kind:{0u,1u})for(unsigned n=0;n<16;++n){Config c;c.kind=kind;c.seed=n;c.sceneNested=true;run(c);}
 for(unsigned kind:{2u,3u})for(uint32_t invalid:{0u,0x5006u,0xffefffu,0xfff000u,0xfff700u,0xfffbfcu,0xffff51u,0x42fff000u}){Config c;c.kind=kind;seed(*resource,c);resource->wide(0x167bc,invalid);check(!T::admitted(T::Kind(kind),{0x0105,true},[&](uint32_t a){return resource->m[a];}),"Admission accepted unsupported pointer");++guards;}
 for(unsigned kind:{2u,3u})for(uint32_t invalid:{0xffefffu,0xfff700u,0x42fff000u,0x80000500u}){Config c;c.kind=kind;seed(*resource,c);auto&r=*resource;T graph(T::Kind(kind),{0x0105,true});while(graph.actionTask().stage()!=(kind==2?ks::StateScreenActionsTask::Stage::ReadPatchToggleOneBase:ks::StateScreenActionsTask::Stage::ReadPatchToggleTwoBase)){const auto cost=graph.nextClocks(r.previous);r.phase(cost);graph.advanceBefore(cost,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,r.previous);if(graph.effect().write)r.previous=-1;}r.wide(0x167bc,invalid);r.phase(graph.nextClocks(r.previous));bool threw=false;try{graph.advanceBefore(r.cost,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,r.previous);}catch(const std::logic_error&){threw=true;}check(threw&&r.size==4,"Actual evolving pointer guard did not stop before derived access");for(unsigned n=0;n<r.size;++n)check(!std::get<0>(r.events[n])&&std::get<1>(r.events[n])==0x167bc+n,"Actual evolving pointer guard accessed derived memory");++guards;}
 check(!allocations&&components==0x7f,"Pure edit action closure/allocation contract");std::cout<<"PASS pure edit actions graphs="<<graphs<<" phases="<<phases<<" budgetRejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" guards="<<guards<<" nestedGraphs="<<nestedGraphs<<" voiceJobs="<<nativeVoiceJobs<<" automaticJobs="<<nativeAutomaticJobs<<" all7roots/components="<<components<<" storage="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
